@sig trait Dispatch_Priority_Resolver_Api {
  def id: Art.BridgeId
  def admission_Id : Art.PortId
  def recovery_plan_Id : Art.PortId
  def selected_intent_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var selected_intent: Factory_Dispatch_Coordinator.Selected_Intent.Type = $

  def put_selected_intent(value : Factory_Dispatch_Coordinator.Selected_Intent.Type) : Unit = {
    Contract(
      Modifies(selected_intent),
      Ensures(
        selected_intent == value
      )
    )
    Spec {
      selected_intent = value
    }

    Art.putValue(selected_intent_Id, Factory_Dispatch_Coordinator.Selected_Intent_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Dispatch_Priority_Resolver_Initialization_Api (
  val id: Art.BridgeId,
  val admission_Id : Art.PortId,
  val recovery_plan_Id : Art.PortId,
  val selected_intent_Id : Art.PortId) extends Dispatch_Priority_Resolver_Api

@datatype class Dispatch_Priority_Resolver_Operational_Api (
  val id: Art.BridgeId,
  val admission_Id : Art.PortId,
  val recovery_plan_Id : Art.PortId,
  val selected_intent_Id : Art.PortId) extends Dispatch_Priority_Resolver_Api {

  // Logika spec var representing port state for incoming data port
  @spec var admission: Factory_Dispatch_Coordinator.Admission_Assessment.Type = $

  def get_admission() : Option[Factory_Dispatch_Coordinator.Admission_Assessment.Type] = {
    Contract(
      Ensures(
        Res == Some(admission)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Admission_Assessment.Type] = Art.getValue(admission_Id) match {
      case Some(Factory_Dispatch_Coordinator.Admission_Assessment_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port admission.  Expecting 'Factory_Dispatch_Coordinator.Admission_Assessment_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.Admission_Assessment.Type]()
      case _ => None[Factory_Dispatch_Coordinator.Admission_Assessment.Type]()
    }
    return value
  }

  // Logika spec var representing port state for incoming data port
  @spec var recovery_plan: Factory_Dispatch_Coordinator.Outcome_Plan.Type = $

  def get_recovery_plan() : Option[Factory_Dispatch_Coordinator.Outcome_Plan.Type] = {
    Contract(
      Ensures(
        Res == Some(recovery_plan)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Outcome_Plan.Type] = Art.getValue(recovery_plan_Id) match {
      case Some(Factory_Dispatch_Coordinator.Outcome_Plan_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port recovery_plan.  Expecting 'Factory_Dispatch_Coordinator.Outcome_Plan_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.Outcome_Plan.Type]()
      case _ => None[Factory_Dispatch_Coordinator.Outcome_Plan.Type]()
    }
    return value
  }
}
